import React from 'react';
import { Link, useNavigate } from 'react-router-dom';
import { useTranslation } from 'react-i18next';
import { ArrowRight, Banknote, ChevronRight, Clock3, MapPin, Package, Phone, Star, Truck, Wifi, WifiOff, Zap } from 'lucide-react';
import { formatShort, formatUZS, nextLabel, weekEarnings } from '../data/mock';
import { useCourier } from '../lib/store';
import { EmptyState, MapView, SectionHead, StatCard, StatusBadge, cn } from '../components/ui';

export const Dashboard = () => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const { courier, orders, online, setOnline, acceptOrder } = useCourier();

  const active = orders.find((o) => ['accepted', 'picked_up', 'on_the_way'].includes(o.status));
  const newOrders = orders.filter((o) => o.status === 'new');
  const delivered = orders.filter((o) => o.status === 'delivered');
  const todayEarnings = delivered.reduce((s, o) => s + o.payout, 0) + (active ? active.payout : 0);
  const maxEarning = Math.max(...weekEarnings.map((d) => d.value));

  const hour = new Date().getHours();
  const greeting = hour < 12 ? t('goodMorning') : hour < 18 ? t('goodAfternoon') : t('goodEvening');

  return (
    <div className="stagger space-y-4">
      {/* hero */}
      <div className="card relative overflow-hidden p-5">
        <span className="pointer-events-none absolute -right-16 -top-20 h-52 w-52 rounded-full bg-brand-400/25 blur-3xl" />
        <span className="pointer-events-none absolute -bottom-16 -left-14 h-40 w-40 rounded-full bg-lime-400/20 blur-3xl" />
        <div className="relative flex items-end justify-between">
          <div>
            <p className="text-[11px] font-bold text-[var(--muted)]">{greeting},</p>
            <h1 className="mt-0.5 font-display text-[22px] font-extrabold tracking-tight">
              {courier.name.split(' ')[0]} <span className="text-gradient">👋</span>
            </h1>
          </div>
          <button
            onClick={() => setOnline(!online)}
            className={cn('flex items-center gap-2 rounded-2xl px-3.5 py-2.5 text-[11px] font-extrabold transition active:scale-95', online ? 'btn-primary' : 'btn-secondary')}
          >
            {online ? <Wifi size={15} /> : <WifiOff size={15} />}
            {online ? t('online') : t('goOnline')}
          </button>
        </div>
        <div className="relative mt-4 grid grid-cols-3 gap-2.5">
          <StatCard icon={<Truck size={17} />} label={t('deliveries')} value={delivered.length + (active ? 1 : 0)} hint={`+${delivered.length} ${t('today')}`} />
          <StatCard icon={<Banknote size={17} />} label={t('earnings')} value={formatShort(todayEarnings)} hint={t('today')} tone="amber" />
          <StatCard icon={<Star size={17} />} label={t('rating')} value={courier.rating} hint={`${courier.deliveries} ${t('deliveries')}`} tone="violet" />
        </div>
      </div>

      {!online && (
        <div className="card p-4 text-center">
          <span className="mx-auto flex h-12 w-12 items-center justify-center rounded-2xl bg-brand-500/10 text-brand-600 dark:text-brand-400"><Zap size={22} /></span>
          <p className="mt-2 text-sm font-extrabold">{t('offline')}</p>
          <p className="mt-0.5 text-[11px] text-[var(--muted)]">{t('noActiveDesc')}</p>
          <button onClick={() => setOnline(true)} className="btn-primary mt-3 btn-sm">{t('goOnline')}</button>
        </div>
      )}

      {/* active delivery */}
      {active ? (
        <div>
          <SectionHead title={t('activeDelivery')} right={<StatusBadge status={active.status} />} />
          <Link to={`/order/${active.id}`} className="card card-lift block overflow-hidden p-3">
            <MapView height="h-48" eta={String(active.eta)} compact />
            <div className="mt-3 flex items-center justify-between gap-2 px-1">
              <div className="min-w-0">
                <p className="font-display text-sm font-extrabold">#{active.id}</p>
                <p className="mt-0.5 flex items-center gap-1 truncate text-[10px] text-[var(--muted)]"><MapPin size={10} /> {active.address}</p>
              </div>
              <div className="shrink-0 text-right">
                <p className="text-[9px] font-bold uppercase tracking-wider text-[var(--muted)]">{t('payout')}</p>
                <p className="font-display text-sm font-extrabold text-gradient">{formatUZS(active.payout)}</p>
              </div>
            </div>
            <div className="card-soft mt-2.5 flex items-center justify-between rounded-2xl px-3.5 py-2.5">
              <span className="flex items-center gap-1.5 text-[10px] font-bold"><Clock3 size={11} className="text-brand-500" /> {active.eta} {t('min')} · {active.distance} {t('km')}</span>
              <span className="flex items-center gap-1 text-[10px] font-extrabold text-brand-600 dark:text-brand-400">{t(nextLabel[active.status])} <ChevronRight size={12} /></span>
            </div>
          </Link>
        </div>
      ) : (
        online && (
          <div>
            <SectionHead title={t('activeDelivery')} />
            <EmptyState icon={<Truck size={26} />} title={t('noActive')} description={t('noActiveDesc')} />
          </div>
        )
      )}

      {/* earnings chart */}
      <div className="card p-4">
        <div className="mb-4 flex items-center justify-between">
          <div>
            <h2 className="font-display text-[15px] font-extrabold tracking-tight">{t('earningsChart')}</h2>
            <p className="mt-0.5 text-[10px] text-[var(--muted)]">{t('weekEarnings')}: <b className="text-gradient font-extrabold">{formatUZS(weekEarnings.reduce((s, d) => s + d.value, 0))}</b></p>
          </div>
          <span className="badge border border-brand-500/25 bg-brand-500/10 text-brand-700 dark:text-brand-300"><span className="text-brand-500">↗</span> +18%</span>
        </div>
        <div className="flex h-32 items-end justify-between gap-2">
          {weekEarnings.map((d, i) => (
            <div key={d.day} className="animate-fade-up flex flex-1 flex-col items-center gap-1.5" style={{ animationDelay: `${i * 60}ms` }}>
              <div className="relative flex w-full flex-1 items-end">
                <span className="mb-1 text-[8px] font-extrabold text-[var(--muted)]">{Math.round(d.value / 1000)}k</span>
                <div className="group relative flex w-full flex-1 items-end">
                  <div className="w-full rounded-xl bg-gradient-to-t from-brand-600 via-brand-500 to-lime-400 shadow-glow transition-all group-hover:brightness-110" style={{ height: `${(d.value / maxEarning) * 100}%` }} />
                </div>
              </div>
              <span className="text-[9px] font-bold text-[var(--muted)]">{d.day}</span>
            </div>
          ))}
        </div>
      </div>

      {/* new orders */}
      <div>
        <SectionHead
          title={<>{t('nextOrders')} <span className="ml-1 rounded-full border border-rose-400/30 bg-rose-500/10 px-2 py-0.5 text-[10px] text-rose-600 dark:text-rose-400">{newOrders.length}</span></>}
          right={<Link to="/orders" className="flex items-center gap-0.5 text-[10px] font-extrabold text-brand-600 dark:text-brand-400">{t('viewAll')} <ArrowRight size={11} /></Link>}
        />
        <div className="stagger space-y-2">
          {newOrders.slice(0, 2).map((o) => (
            <div key={o.id} className="card card-lift p-3.5">
              <div className="flex items-start justify-between gap-2">
                <div>
                  <p className="text-[11px] font-extrabold">#{o.id} · {o.customer}</p>
                  <p className="mt-0.5 flex items-center gap-1 text-[10px] text-[var(--muted)]"><MapPin size={9} /> {o.address}</p>
                </div>
                <p className="shrink-0 font-display text-[11px] font-extrabold text-gradient">{formatUZS(o.payout)}</p>
              </div>
              <div className="mt-3 flex items-center justify-between">
                <span className="flex items-center gap-2 text-[9px] font-bold text-[var(--muted)]"><Clock3 size={11} className="text-brand-500" />{o.distance} {t('km')} · {o.eta} {t('min')} · {o.items.length} {t('items')}</span>
                <div className="flex gap-1.5">
                  <button onClick={() => navigate(`/order/${o.id}`)} className="btn-secondary btn-sm px-2.5">{t('orderDetails')}</button>
                  <button onClick={() => acceptOrder(o.id)} className="btn-primary btn-sm px-2.5">{t('accept')}</button>
                </div>
              </div>
            </div>
          ))}
          {newOrders.length === 0 && <div className="card p-4 text-center text-[11px] text-[var(--muted)]">{t('noOrders')}</div>}
        </div>
      </div>

      {/* quick links */}
      <div className="grid grid-cols-2 gap-2.5">
        <a href="tel:+998712000000" className="card card-lift flex items-center gap-2.5 p-3.5">
          <span className="flex h-10 w-10 items-center justify-center rounded-2xl bg-sky-400/15 text-sky-600 dark:text-sky-400"><Phone size={16} /></span>
          <div><p className="text-[10px] font-extrabold">{t('support')}</p><p className="text-[9px] text-[var(--muted)]">24/7</p></div>
        </a>
        <Link to="/orders" className="card card-lift flex items-center gap-2.5 p-3.5">
          <span className="flex h-10 w-10 items-center justify-center rounded-2xl bg-violet-400/15 text-violet-600 dark:text-violet-400"><Package size={16} /></span>
          <div><p className="text-[10px] font-extrabold">{t('history')}</p><p className="text-[9px] text-[var(--muted)]">{orders.length} {t('orders')}</p></div>
        </Link>
      </div>
    </div>
  );
};
